/**
 * Geodata generated by scripts/build_gis.py from Natural Earth + AWS Terrain Tiles.
 * Do not edit by hand — re-run the script instead.
 */
import type { FeatureCollection, LineString, MultiPolygon, Polygon, MultiLineString } from 'geojson'
import country from './country.json'
import neighbours from './neighbours.json'
import regions from './regions.json'
import lakes from './lakes.json'
import glaciers from './glaciers.json'
import rivers from './rivers.json'
import streams from './streams.json'
import ridges from './ridges.json'
import rasters from './rasters.json'
import stations from './climate_stations.json'
import stats from './stats.json'

type Poly = Polygon | MultiPolygon
type Line = LineString | MultiLineString

export const geo = {
  country: country as unknown as FeatureCollection<Poly, { id: string }>,
  neighbours: neighbours as unknown as FeatureCollection<Poly, { iso: string }>,
  regions: regions as unknown as FeatureCollection<Poly, { id: string; iso: string }>,
  lakes: lakes as unknown as FeatureCollection<Poly, { id: string; kind: string }>,
  glaciers: glaciers as unknown as FeatureCollection<Poly, { id: string }>,
  rivers: rivers as unknown as FeatureCollection<Line, { id: string; src_elev: number; end_elev: number }>,
  streams: streams as unknown as FeatureCollection<Line, { o: number }>,
  ridges: ridges as unknown as FeatureCollection<Line, { id: string; dem_max: number; dem_mean: number }>,
}

/** [[south, west], [north, east]] of the raster overlays */
export const rasterBounds = rasters.bounds as [[number, number], [number, number]]
export const heightmapMeta = rasters.heightmap
export const demStats = stats

export interface ClimateStation {
  id: string
  ghcn: string
  lat: number
  lon: number
  elev: number
  temp: number[] | null
  tempPeriod: string | null
  tempYears: number
  prcp: number[] | null
  prcpPeriod: string | null
  prcpYears: number
}
export const climateStations = stations as ClimateStation[]

export const KG_BOUNDS: [[number, number], [number, number]] = [
  [39.19, 69.23],
  [43.26, 80.26],
]

export const asset = (p: string) => `${import.meta.env.BASE_URL}${p}`
